3	import java.util.List;
4	import java.util.regex.Pattern;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
9	
10	/**
11	 * Optional email: when absent the request is untouched; when present it must be a syntactically
12	 * valid address, stored lower-cased in place so the entity and the response both carry it. An
13	 * invalid address rejects with 400 via {@link MissingOwnerFieldsException}.
14	 */
15	public class NormalizeOwnerEmail {
16	
17	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
18	
19	    public void service(@Val OwnerFieldsDto request) throws MissingOwnerFieldsException {
20	        String email = request.getEmail();
21	        if (email == null) {
22	            return;
23	        }
24	        if (!EMAIL.matcher(email).matches()) {
25	            throw new MissingOwnerFieldsException(List.of("email"));
26	        }
27	        request.setEmail(email.toLowerCase());
28	    }
29	}
